INSERT INTO public.reviews (pro_id,author_name,author_place,rating,title,body,job_type) VALUES
('marcus-webb','Hannah D.','Bristol',5,'Bathroom done in four days','Three quotes in under two hours, all with photos of previous work. Picked the middle one and the bathroom was done in four days.','Bathroom refit'),
('marcus-webb','Peter S.','Clevedon',5,'Sorted a leak same day','Rang at 8am with water coming through the ceiling. Marcus was there by eleven and had it capped and repaired by two.','Emergency leak'),
('marcus-webb','Louise K.','Bristol',4,'Good boiler install','Tidy boiler swap, explained the controls properly. Took half a day longer than quoted but no extra charge.','Boiler installation'),
('priya-shah','Ade O.','Manchester',5,'Actually turned up','I had been ghosted by two electricians before this. Priya turned up when she said she would, which is all I wanted.','Consumer unit upgrade'),
('priya-shah','Marianne T.','Stockport',5,'EV charger, no fuss','Quoted on a video call, installed a week later, handled the DNO paperwork herself.','EV charger installation'),
('tom-halloran','Ruth M.','Leeds',5,'Beautiful wardrobes','Being able to read real reviews rather than a star rating with no detail made the difference. No haggling, no hard sell.','Fitted wardrobes'),
('tom-halloran','David B.','Harrogate',4,'Lovely staircase work','Genuine craftsmanship on a Victorian staircase. Slow to reply at first but worth waiting for.','Staircase repair'),
('dean-okafor','Femi A.','London',5,'Extension on time','Six-week rear extension finished on the day he said it would be. Weekly written updates.','Rear extension'),
('dean-okafor','Clare W.','London',4,'Solid loft conversion','Good work and clean site. Some back and forth on the final invoice but resolved fairly.','Loft conversion'),
('sian-roberts','Gareth P.','Cardiff',5,'Drone survey was a nice touch','Showed me photos of the actual damage before quoting. Re-roofed in three days.','Re-roof'),
('alan-petrie','Morag F.','Glasgow',5,'Immaculate finish','Two rooms and a hallway, not a single spot of paint anywhere it should not be.','Interior decorating'),
('kirsty-lam','Ben J.','London',5,'Wet room is perfect','Large-format porcelain, dead level, grout lines you could set a watch by.','Wet room tiling'),
('greg-mullen','Aisha R.','Birmingham',5,'Fast and clean','Whole ceiling skimmed and cleaned up in a day.','Ceiling skim'),
('nadia-hussain','Tom E.','Manchester',4,'Great garden design','Design was lovely. Planting took a fortnight longer than planned due to weather.','Garden design'),
('bill-carter','Sue H.','Newcastle',5,'Nothing was too small','Put up six shelves, fixed a door and rehung a gate. Charged less than quoted.','Odd jobs'),
('joe-brennan','Nikhil G.','London',5,'Unvented cylinder swap','Explained the options honestly instead of upselling. Great work.','Cylinder replacement'),
('emma-clyde','Fiona M.','Glasgow',4,'Smart lighting sorted','Set up the whole downstairs on smart switches and left it working properly.','Smart lighting');
